const PRICES: Record<string, number> = {
  apple: 150,
  banana: 75,
  cherry: 300,
};

async function fetchPrice(sku: string): Promise<number> {
  return PRICES[sku] ?? 0;
}

// Return the total price of all skus (0 for an empty list).
// BUG: Array.prototype.forEach does not await async callbacks - the function
// returns `total` before any of the awaits inside have resolved, so the
// result is always 0.
export async function totalPrice(skus: string[]): Promise<number> {
  let total = 0;
  skus.forEach(async (sku) => {
    total += await fetchPrice(sku);
  });
  return total;
}

