const assert = require("assert");
const { totalPrice } = require("./build/prices.js");

async function main() {
  assert.strictEqual(await totalPrice(["apple", "banana"]), 225);
  assert.strictEqual(await totalPrice(["apple", "banana", "cherry"]), 525);
  assert.strictEqual(await totalPrice(["unknown"]), 0);
  assert.strictEqual(await totalPrice([]), 0, "empty list must total 0");
  console.log("behavior OK");
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

