files.prices.ts:
const PRICES: Record<string, number> = {
  apple: 150,
  banana: 75,
  cherry: 300,
};

async function fetchPrice(sku: string): Promise<number> {
  return PRICES[sku] ?? 0;
}

export async function totalPrice(skus: string[]): Promise<number> {
  const prices = await Promise.all(skus.map((sku) => fetchPrice(sku)));
  return prices.reduce((a, b) => a + b);
}
